def trans(m, k):
 a=np.array(m)
 if k>=4: a=np.fliplr(a)
 return np.rot90(a,k%4).tolist()
for k in range(8):
 xs=[]; ys=[]
 for L,R,O in zip(Ls,Rs,Os):
  Rt=trans(R,k)
  for r in range(4):
   for c in range(4): xs.append((L[r][c],Rt[r][c]));ys.append(O[r][c])
 # all boolean function truthsets
 funcs=[]
 for mask in range(16):
  err=sum((((mask>> (x*2+y))&1)!=o) for (x,y),o in zip(xs,ys))
  if err==0: funcs.append(mask)
 print(k, funcs)

def neighbor_counts(m,r,c):
 return sum(m[rr][cc] for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)] if 0<=rr<4 and 0<=cc<4)
for idx,(L,R,O) in enumerate(zip(Ls,Rs,Os),1):
 print('\n',idx)
 for r in range(4):
  for c in range(4):
   if O[r][c]: print((r+1,c+1),'L/R',L[r][c],R[r][c],'nb',neighbor_counts(L,r,c),neighbor_counts(R,r,c))
